---
name: policy-ux
description: UX standard of the todo app team (version 2). Rules for feedback on failures, confirmations, screen states, wording and accessibility. Load it whenever you write or review a spec, design or UI code for the app.
version: 2
owner: Linh (UX owner, simulated) · backup: Thảo (product owner, simulated)
---

# UX standard · v2

Sample standard for the demo. Each rule has an ID; cite it as `policy-ux@2#U<n>`.

- **U1.** Never lose the user's data silently. Any failed save is shown on the same screen, in plain words, with what the user can do
  next.
- **U2.** No confirmation dialogs for actions on a single item: they happen at once and offer **Undo** for 10 seconds instead.
  Actions that overwrite or delete more than one item follow `policy-security#S2` (confirm first). *(Changed in v2, agreed by the UX
  and security owners, 2026-10-20.)*
- **U3.** Every list or screen defines its empty, loading and error states.
- **U4.** UI text is Vietnamese, short, and free of technical words (no "localStorage", "JSON", "console").
- **U5.** Every control works with the keyboard and has an accessible label.
// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
// Saving and importing decisions live in backup.js (persist, importBackup); this file only wires them to the page.
let todos = store.load().todos;
let filter = 'all';

const $ = (sel) => document.querySelector(sel);

function add(title) {
  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
  commit();
}

function toggle(id) {
  const t = todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
  commit();
}

function remove(id) {
  todos = todos.filter((x) => x.id !== id);
  commit();
}

function commit() {
  show(persist(store, todos).message);
  render();
}

function show(message) {
  $('#message').textContent = message || '';
}

function visible() {
  if (filter === 'open') return todos.filter((t) => !t.done);
  if (filter === 'done') return todos.filter((t) => t.done);
  return todos;
}

function render() {
  const list = $('#list');
  list.innerHTML = '';
  for (const t of visible()) {
    const li = document.createElement('li');
    li.className = t.done ? 'done' : '';
    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
    li.querySelector('span').textContent = t.title;
    li.querySelector('input').onchange = () => toggle(t.id);
    li.querySelector('button').onclick = () => remove(t.id);
    list.append(li);
  }
  const open = todos.filter((t) => !t.done).length;
  // Every todo done (and the list not empty): say so instead of "0 việc chưa xong" (Thảo, PR 3).
  $('#count').textContent = open === 0 && todos.length > 0 ? 'Đã xong hết' : `${formatCount(open)} việc chưa xong`;
  $('#unreadable').hidden = !store.readError;
  // Based on the whole list, not the filter; and not shown on a read error, where the list only looks empty.
  $('#empty').hidden = todos.length > 0 || store.readError;
}

// Resolves true only when the customer picks "Thay"; Esc and "Huỷ" resolve false.
function ask(question) {
  const dialog = $('#confirm');
  $('#confirm-text').textContent = question;
  dialog.returnValue = '';
  dialog.showModal();
  return new Promise((resolve) => {
    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'yes'), { once: true });
  });
}

$('#add').onsubmit = (e) => {
  e.preventDefault();
  const input = $('#title');
  if (input.value.trim()) add(input.value);
  input.value = '';
};

$('#filters').onclick = (e) => {
  const f = e.target.dataset.filter;
  if (!f) return;
  filter = f;
